<?php require_once __DIR__.'/../funciones.php'; exigir_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){$accion=$_POST['accion']??'';if($accion==='guardar'){$id=(int)($_POST['id']??0);$nombre=trim($_POST['nombre']??'');$desc=trim($_POST['descripcion']??'');$cat=trim($_POST['categoria']??'');$precio=(float)($_POST['precio']??0);$imagen=trim($_POST['imagen']??'');if($nombre===''||$precio<0){aviso('Nombre y precio válido son obligatorios.','error');header('Location: productos.php');exit;}if($id){$q=$conn->prepare('UPDATE productos SET nombre=?,descripcion=?,categoria=?,precio=?,imagen=? WHERE id=?');$q->bind_param('sssdsi',$nombre,$desc,$cat,$precio,$imagen,$id);}else{$q=$conn->prepare('INSERT INTO productos(nombre,descripcion,categoria,precio,imagen) VALUES(?,?,?,?,?)');$q->bind_param('sssds',$nombre,$desc,$cat,$precio,$imagen);}$q->execute();aviso('Producto guardado correctamente.');}elseif($accion==='eliminar'){$id=(int)$_POST['id'];$q=$conn->prepare('DELETE FROM productos WHERE id=?');$q->bind_param('i',$id);$q->execute();aviso('Producto eliminado.');}elseif($accion==='estado'){$id=(int)$_POST['id'];$q=$conn->prepare('UPDATE productos SET activo=1-activo WHERE id=?');$q->bind_param('i',$id);$q->execute();aviso('Disponibilidad actualizada.');}header('Location: productos.php');exit;}
$editar=null;if(isset($_GET['editar'])){$id=(int)$_GET['editar'];$q=$conn->prepare('SELECT * FROM productos WHERE id=?');$q->bind_param('i',$id);$q->execute();$editar=$q->get_result()->fetch_assoc();}$rs=$conn->query('SELECT * FROM productos ORDER BY id DESC');?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Productos</title><link rel="stylesheet" href="../estilos.css"></head><body><?php include 'menu.php';?><main class="contenedor"><h1 class="titulo">Administrar productos</h1><?php mostrar_aviso();?><div class="panel"><h2 class="titulo"><?=$editar?'Editar producto':'Agregar nuevo producto'?></h2><form method="post"><input type="hidden" name="accion" value="guardar"><input type="hidden" name="id" value="<?=e($editar['id']??0)?>"><div class="tarjetas"><div class="campo"><label>Nombre</label><input name="nombre" required value="<?=e($editar['nombre']??'')?>"></div><div class="campo"><label>Categoría</label><input name="categoria" value="<?=e($editar['categoria']??'Plato de fondo')?>"></div><div class="campo"><label>Precio (S/)</label><input type="number" name="precio" min="0" step="0.01" required value="<?=e($editar['precio']??'')?>"></div><div class="campo"><label>Ruta de imagen</label><input name="imagen" placeholder="imagenes/plato1.jpg" value="<?=e($editar['imagen']??'')?>"></div></div><div class="campo"><label>Descripción</label><textarea name="descripcion" rows="2"><?=e($editar['descripcion']??'')?></textarea></div><button class="btn">Guardar producto</button> <?php if($editar):?><a class="btn btn-claro" href="productos.php">Cancelar</a><?php endif;?></form></div><br><div class="panel tabla-wrap"><h2 class="titulo">Listado de productos</h2><table><tr><th>Producto</th><th>Categoría</th><th>Precio</th><th>Estado</th><th>Acciones</th></tr><?php while($p=$rs->fetch_assoc()):?><tr><td><?=e($p['nombre'])?></td><td><?=e($p['categoria'])?></td><td>S/ <?=number_format($p['precio'],2)?></td><td><?=$p['activo']?'Disponible':'Oculto'?></td><td><div class="acciones"><a class="btn btn-claro" href="?editar=<?=$p['id']?>">Editar</a><form method="post"><input type="hidden" name="accion" value="estado"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn btn-claro">Activar/Ocultar</button></form><form method="post" onsubmit="return confirm('¿Eliminar este producto?')"><input type="hidden" name="accion" value="eliminar"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn btn-vino">Eliminar</button></form></div></td></tr><?php endwhile;?></table></div></main></body></html>
